head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _1 : mergeOptionStr = never / bycol / byrow (기본 병합 방식). bycolrec/byrowrec/byrestric* 는 _2~_4 담당.
scwin.tData = {
    "description" : "[gridView > M > mergeCellsFixedRows]<br/>GridView 컴포넌트의 mergeCellsFixedRows 속성을 설정합니다.",
    "validation" : [
        "fixedRow 로 고정된 Row 영역에만 적용되며, fixedColumn, fixedRightColumn 속성으로 고정된 Column 영역에는 적용되지 않습니다.",
        "mergeCellsFixedRows 속성 설정 시 mergeCellsFixedCols 속성은 무시됩니다.",
        "displayFormat 등의 포맷 속성이 적용되지 않은 원본 데이터와 초기 Column 위치를 기준으로 병합 처리됩니다.",
        "mergeOptionStr 'never' 설정 시 고정 Row 영역에서 동일 Cell 값에 대한 병합을 수행하지 않습니다.",
        "mergeOptionStr 'bycol' 설정 시 같은 Column 내에서 동일한 값이 연속되는 Cell 에 rowSpan 방식의 세로 병합을 수행합니다.",
        "mergeOptionStr 'byrow' 설정 시 같은 Row 내에서 동일한 값이 연속되는 Cell 에 colSpan 방식의 가로 병합을 수행합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — 고정 Row 영역(행0~행1) 과 비고정 Row 영역(행2~행7) 의 병합 차이를 보여주도록 구성. (P_mergeCellsFixedRows_1 과 동일 데이터)
//  · 행0(고정) : A,A,A,1000   → 가로(byrow) 동일값 연속 : col1~col3=A / 세로로도 행1 과 동일값
//  · 행1(고정) : A,B,B,1000   → col1 이 행0 과 같은 A → 세로(bycol) 병합 검증용 / col2=col3=B 가로 동일값
//  · 행2~행7(비고정) : 서로 다른 값(C,D,E,…)으로 두어 어떤 옵션에서도 미병합(비고정 Row 미병합 대비, validation #1)
//  · col4(displayFormat="#,##0") : 표시값은 1,000 이나 병합은 원본(1000) 기준(validation #3)
scwin.MERGE_DATA = [
    { "col1": "A", "col2": "A", "col3": "A", "col4": "1000" },
    { "col1": "A", "col2": "B", "col3": "B", "col4": "1000" },
    { "col1": "C", "col2": "c1", "col3": "c2", "col4": "2000" },
    { "col1": "D", "col2": "d1", "col3": "d2", "col4": "3000" },
    { "col1": "E", "col2": "e1", "col3": "e2", "col4": "4000" },
    { "col1": "F", "col2": "f1", "col3": "f2", "col4": "5000" },
    { "col1": "G", "col2": "g1", "col3": "g2", "col4": "6000" },
    { "col1": "H", "col2": "h1", "col3": "h2", "col4": "7000" }
];



// comp 생성 : fixedRow=2 (행0~행1 고정) 그리드 1개를 동적 생성한다. (P_mergeCellsFixedRows_1 과 동일 구성)
//  ★ mergeCellsFixedRows 는 생성 attribute 로 주지 않는다. (초기 미병합 상태로 생성 후 mergeCellsFixedRows() 메소드로 적용)
//     col4 : displayFormat="#,##0" (원본 1000 vs 표시 1,000)
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="fixedRow=2(행0~행1 고정 → 병합 대상), col4=displayFormat(#,##0). 고정 Row 영역만 병합되고 비고정 Row(행2~행7)는 미병합. par_mergeOptionStr 선택 후 mergeCellsFixedRows 버튼으로 적용. 세로 스크롤 시 고정 Row(상단)는 남고 비고정 Row 만 스크롤됨"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // fixedRow=2 으로 상단 2개 Row 고정
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id,
        fixedRow: 2
    });

    // target 생성 (mergeCellsFixedRows 속성은 부여하지 않음 → 버튼에서 메소드로 적용)
    //  · col4 : displayFormat="#,##0" (원본 1000 vs 표시 1,000)
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:420px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCellsFixedRows sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column1" value="col1"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column2" value="col2"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="column4" value="col4(포맷)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="180" style="" dataType="number" displayFormat="#,##0" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// mergeCellsFixedRows 실행 : par_mergeOptionStr 값(필수)으로 target1.mergeCellsFixedRows(mergeOptionStr) 호출
scwin.btn_mergeCellsFixedRows_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let mode = par_mergeOptionStr.getValue();

    target1.mergeCellsFixedRows(mode);

    bottom.setReturnValue("[옵션] mergeCellsFixedRows=" + target1.options.mergeCellsFixedRows + " / fixedRow=" + target1.options.fixedRow + " / mergeOptionStr='" + mode + "'");

    scwin.printMergeState(bottom);
}



// 병합 상태 확인 : 고정 Row 영역 td 의 rowSpan/colSpan 을 직관 출력(⬇세로/➡가로) + 비고정 Row(행2~행7) 미병합 확인
//  - td 셀렉터는 gid = target1.id 사용(e.target.id 는 버튼 id 라 사용 불가)
//  - 고정 Row 영역 td 는 _fixedRowDiv 안에 위치하며 id 는 target1_cell_{row}_{col} 형태(scroll 영역과 중복 id 가능)
//  - 화면에 표시되는(흡수되지 않은) td 만 대상으로 rowSpan/colSpan 을 읽어 판정 (중복 키 제외)
scwin.printMergeState = function (bottom) {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let rowSpanCnt = 0;
    let colSpanCnt = 0;
    let nonFixedMerged = false;
    let descs = [];
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        // 흡수되어 화면에 표시되지 않는 td 제외
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);

        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        if (rs > 1 || cs > 1) {
            // 비고정 Row(행2 이상)에 병합이 걸렸는지 (시작 행이 2 이상)
            if (r >= 2) nonFixedMerged = true;
            if (rs > 1) rowSpanCnt++;
            if (cs > 1) colSpanCnt++;
            let val = (td.textContent || "").trim();
            if (rs > 1 && cs === 1) {
                descs.push("⬇ col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
            } else if (cs > 1 && rs === 1) {
                descs.push("➡ 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
            } else {
                descs.push("⬛ [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록병합(" + rs + "x" + cs + ") = '" + val + "'");
            }
        }
    }

    let modeName;
    if (rowSpanCnt === 0 && colSpanCnt === 0) modeName = "never (병합 없음)";
    else if (rowSpanCnt > 0 && colSpanCnt === 0) modeName = "bycol (세로 병합)";
    else if (colSpanCnt > 0 && rowSpanCnt === 0) modeName = "byrow (가로 병합)";
    else modeName = "혼합(블록) 병합";

    bottom.setReturnValue("판정 : " + modeName + " / 병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }
    bottom.setReturnValue("비고정 Row(행2~행7) 영역 병합 여부 : " + nonFixedMerged + " (false 면 비고정 Row 미병합 → 고정 Row 영역에만 적용)");
}
